    return os.path.getsize(filepath) > 0

def check_file_has_columns(filepath, expected_columns):
    """Check if file has the expected columns."""
    try:
        with open(filepath, 'r', newline='', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader)
            return header == expected_columns
    except Exception:
        return False

def check_file_has_data(filepath):
    """Check if file has at least one data row."""
    try:
        with open(filepath, 'r', newline='', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader)
            rows = list(reader)
            return len(rows) > 0
    except Exception:
        return False

def check_column_types(filepath, expected_columns, col_types):
    """Check if column data has expected types."""
    try:
        with open(filepath, 'r', newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            rows = list(reader)
            for row in rows:
                for col_idx, col_type in col_types.items():
                    if col_idx in row:
                        value = row[col_idx]
                        # Skip empty values
                        if value.strip():
                            try:
                                if col_type == 'float':
                                    float(value)
                                elif col_type == 'int':
                                    int(value)
                            except ValueError:
                                return False
        return True
    except Exception:
        return False

