                        "message": f"File {filename} {'has valid column types' if check_column_types(filepath, EXPECTED_COLUMNS[filename], col_types[filename]) else 'has invalid column types'}"
                    })

    return results

def main():
    """Main entry point."""
    results = run_checks()

    # Write results to JSON file
    output_path = "outputs/t14_validation_summary.json"
    with open(output_path, 'w', encoding='utf-8') as f:
